-- A255: ficha operacional física por Lote; não cria disponibilidade, preço, venda, contrato ou financeiro.
create table public.subdivision_lot_internal_notes (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict, lot_id uuid not null, internal_note text not null check (char_length(trim(internal_note)) between 1 and 280 and internal_note !~* '(\mcpf\M|\mcnpj\M|\mr\$\M|@|\mcontrato\M|\mcobrança\M|\mpagamento\M)'), created_by uuid not null references public.identity_subjects(user_id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint subdivision_lot_internal_notes_lot_fk foreign key(lot_id,organization_id) references public.subdivision_lots(id,organization_id) on delete restrict, constraint subdivision_lot_internal_notes_unique unique(organization_id,lot_id));
alter table public.subdivision_lot_internal_notes enable row level security; revoke all on table public.subdivision_lot_internal_notes from public,anon,authenticated;
create or replace function public.subdivision_list_draft_physical_structure_v3(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text,p_development_id uuid) returns table(block_id uuid,block_number integer,sector_reference text,block_typology public.subdivision_block_typology,lots jsonb) language plpgsql security definer set search_path='' as $$ begin perform private.require_active_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code); if not exists(select 1 from public.subdivision_developments d where d.id=p_development_id and d.organization_id=p_organization_id and d.state='draft'::public.party_lifecycle_state) then raise exception using errcode='42501',message='SUBDIVISION_DEVELOPMENT_CONTEXT_DENIED'; end if; return query select block.id,block.block_number,block.sector_reference,block.block_typology,coalesce(jsonb_agg(jsonb_build_object('lot_number',lot.lot_number,'area_sqm',lot.area_sqm,'frontage_m',lot.frontage_m,'depth_m',lot.depth_m,'lot_typology',lot.lot_typology::text,'position_code',lot.position_code::text,'reservation_purpose',reservation.reservation_purpose::text,'internal_note',note.internal_note) order by lot.lot_number) filter(where lot.id is not null),'[]'::jsonb) from public.subdivision_blocks block left join public.subdivision_lots lot on lot.block_id=block.id and lot.organization_id=p_organization_id and lot.state='draft'::public.party_lifecycle_state left join public.subdivision_lot_physical_reservations reservation on reservation.lot_id=lot.id and reservation.organization_id=lot.organization_id left join public.subdivision_lot_internal_notes note on note.lot_id=lot.id and note.organization_id=lot.organization_id where block.organization_id=p_organization_id and block.development_id=p_development_id and block.state='draft'::public.party_lifecycle_state group by block.id,block.block_number,block.sector_reference,block.block_typology order by block.block_number,block.id; end; $$;
create or replace function public.subdivision_upsert_draft_lot_operational_profile_v1(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text,p_development_id uuid,p_block_id uuid,p_lot_number integer,p_area_sqm numeric,p_frontage_m numeric,p_depth_m numeric,p_lot_typology public.subdivision_lot_typology,p_position_code public.subdivision_lot_position,p_reservation_purpose public.subdivision_lot_physical_reservation_purpose,p_internal_note text,p_correlation_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare v_lot_id uuid; v_existing uuid; begin perform private.require_active_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code); select target_id into v_existing from public.admin_audit_events where command_name='subdivision_upsert_draft_lot_operational_profile_v1' and correlation_id=p_correlation_id and actor_user_id=p_actor_user_id and organization_id=p_organization_id and outcome='allowed' limit 1; if v_existing is not null then return; end if; select lot.id into v_lot_id from public.subdivision_lots lot join public.subdivision_blocks block on block.id=lot.block_id and block.organization_id=lot.organization_id where lot.organization_id=p_organization_id and lot.block_id=p_block_id and lot.lot_number=p_lot_number and lot.state='draft'::public.party_lifecycle_state and block.state='draft'::public.party_lifecycle_state and block.development_id=p_development_id; if v_lot_id is null then raise exception using errcode='42501',message='SUBDIVISION_LOT_CONTEXT_DENIED'; end if; update public.subdivision_lots set area_sqm=p_area_sqm,frontage_m=p_frontage_m,depth_m=p_depth_m,lot_typology=p_lot_typology,position_code=p_position_code,updated_at=now() where id=v_lot_id and organization_id=p_organization_id; if p_reservation_purpose is null then delete from public.subdivision_lot_physical_reservations where organization_id=p_organization_id and lot_id=v_lot_id; else insert into public.subdivision_lot_physical_reservations(organization_id,lot_id,reservation_purpose,created_by) values(p_organization_id,v_lot_id,p_reservation_purpose,p_actor_user_id) on conflict(organization_id,lot_id) do update set reservation_purpose=excluded.reservation_purpose,created_by=excluded.created_by,updated_at=now(); end if; if p_internal_note is null then delete from public.subdivision_lot_internal_notes where organization_id=p_organization_id and lot_id=v_lot_id; else insert into public.subdivision_lot_internal_notes(organization_id,lot_id,internal_note,created_by) values(p_organization_id,v_lot_id,btrim(p_internal_note),p_actor_user_id) on conflict(organization_id,lot_id) do update set internal_note=excluded.internal_note,created_by=excluded.created_by,updated_at=now(); end if; insert into public.admin_audit_events(correlation_id,actor_user_id,organization_id,command_name,outcome,target_type,target_id,payload_redacted) values(p_correlation_id,p_actor_user_id,p_organization_id,'subdivision_upsert_draft_lot_operational_profile_v1','allowed','subdivision_lot',v_lot_id,jsonb_build_object('module',p_module::text,'purpose_code',btrim(p_purpose_code),'physical_profile_updated',true,'has_internal_note',p_internal_note is not null,'has_reserved_purpose',p_reservation_purpose is not null)); end; $$;
revoke all on function public.subdivision_list_draft_physical_structure_v3(uuid,uuid,public.operating_module,text,uuid),public.subdivision_upsert_draft_lot_operational_profile_v1(uuid,uuid,public.operating_module,text,uuid,uuid,integer,numeric,numeric,numeric,public.subdivision_lot_typology,public.subdivision_lot_position,public.subdivision_lot_physical_reservation_purpose,text,uuid) from public,anon,authenticated; grant execute on function public.subdivision_list_draft_physical_structure_v3(uuid,uuid,public.operating_module,text,uuid),public.subdivision_upsert_draft_lot_operational_profile_v1(uuid,uuid,public.operating_module,text,uuid,uuid,integer,numeric,numeric,numeric,public.subdivision_lot_typology,public.subdivision_lot_position,public.subdivision_lot_physical_reservation_purpose,text,uuid) to service_role;
